import { findById } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title || !input.title.trim()) {
      throw new Error('Title is required');
    }
    if (!['open', 'in_progress', 'done'].includes(input.status)) {
      throw new Error('Invalid status');
    }
    findById(input.createdBy);
    findById(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);
    this.cache.set(task.id, task, 60000);
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });
    return task;
  }

  getTask(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const validTransitions: Record<string, string[]> = {
      open: ['in_progress'],
      in_progress: ['done'],
      done: [],
    };

    if (!validTransitions[task.status].includes(status)) {
      throw new Error(`Invalid status transition: ${task.status} -> ${status}`);
    }

    task.status = status;
    this.cache.invalidate(id);
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });
    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;
    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);
    this.cache.invalidate(id);
    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });
    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  listAll(): Task[] {
    return Array.from(this.tasks.values());
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
", "path": "src/tasks.ts"}

